CREATE TYPE "GameStatus" AS ENUM ('ACTIVE','SUSPENDED','ARCHIVED');
CREATE TYPE "DrawStatus" AS ENUM ('SCHEDULED','OPEN','CLOSED','RESULT_PENDING','RESULT_PUBLISHED','CANCELLED');
CREATE TYPE "LimitScope" AS ENUM ('TENANT','BRANCH','MERCHANT','GAME','DRAW','BET_TYPE','NUMBER');
CREATE TABLE "Game" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"code" VARCHAR(40) NOT NULL,"name" VARCHAR(160) NOT NULL,"description" TEXT,"status" "GameStatus" NOT NULL DEFAULT 'ACTIVE',"cutoffSeconds" INTEGER NOT NULL DEFAULT 300,"resultDigits" INTEGER NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"archivedAt" TIMESTAMPTZ,UNIQUE("tenantId","code"));
CREATE TABLE "Market" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"code" VARCHAR(40) NOT NULL,"name" VARCHAR(120) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","code"));
CREATE TABLE "BetType" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"code" VARCHAR(40) NOT NULL,"name" VARCHAR(120) NOT NULL,"selectionCount" INTEGER NOT NULL,"numberMin" INTEGER NOT NULL,"numberMax" INTEGER NOT NULL,"allowRepeats" BOOLEAN NOT NULL DEFAULT false,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("tenantId","code"));
CREATE TABLE "GameBetType" ("gameId" UUID NOT NULL REFERENCES "Game"("id") ON DELETE CASCADE,"betTypeId" UUID NOT NULL REFERENCES "BetType"("id") ON DELETE RESTRICT,"active" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("gameId","betTypeId"));
CREATE TABLE "GameSchedule" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"gameId" UUID NOT NULL REFERENCES "Game"("id") ON DELETE CASCADE,"marketId" UUID REFERENCES "Market"("id") ON DELETE SET NULL,"weekday" INTEGER NOT NULL CHECK("weekday" BETWEEN 0 AND 6),"opensAt" VARCHAR(5) NOT NULL,"closesAt" VARCHAR(5) NOT NULL,"resultAt" VARCHAR(5) NOT NULL,"timezone" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("gameId","marketId","weekday","resultAt"));
CREATE TABLE "Draw" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"gameId" UUID NOT NULL REFERENCES "Game"("id") ON DELETE RESTRICT,"drawNumber" VARCHAR(60) NOT NULL,"drawDate" DATE NOT NULL,"opensAt" TIMESTAMPTZ NOT NULL,"closesAt" TIMESTAMPTZ NOT NULL,"resultAt" TIMESTAMPTZ NOT NULL,"status" "DrawStatus" NOT NULL DEFAULT 'SCHEDULED',"result" JSONB,"createdById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"publishedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","drawNumber"),CHECK("opensAt"<"closesAt"),CHECK("closesAt"<="resultAt"));
CREATE TABLE "OddsRule" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"gameId" UUID NOT NULL REFERENCES "Game"("id") ON DELETE RESTRICT,"betTypeId" UUID NOT NULL REFERENCES "BetType"("id") ON DELETE RESTRICT,"multiplier" NUMERIC(19,6) NOT NULL CHECK("multiplier">0),"startsAt" TIMESTAMPTZ NOT NULL,"endsAt" TIMESTAMPTZ,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "LotteryRule" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"jurisdictionCode" VARCHAR(20) NOT NULL,"key" VARCHAR(100) NOT NULL,"value" JSONB NOT NULL,"effectiveFrom" TIMESTAMPTZ NOT NULL,"effectiveTo" TIMESTAMPTZ,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("tenantId","jurisdictionCode","key","effectiveFrom"));
CREATE TABLE "BettingLimit" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"scope" "LimitScope" NOT NULL,"scopeId" UUID,"gameId" UUID REFERENCES "Game"("id") ON DELETE CASCADE,"drawId" UUID REFERENCES "Draw"("id") ON DELETE CASCADE,"betTypeId" UUID REFERENCES "BetType"("id") ON DELETE CASCADE,"numberKey" VARCHAR(80),"minStake" NUMERIC(19,4),"maxStake" NUMERIC(19,4),"maxExposure" NUMERIC(19,4),"active" BOOLEAN NOT NULL DEFAULT true,"startsAt" TIMESTAMPTZ NOT NULL,"endsAt" TIMESTAMPTZ,CHECK("minStake" IS NULL OR "minStake">=0),CHECK("maxStake" IS NULL OR "maxStake">=COALESCE("minStake",0)));
CREATE INDEX "game_tenant_status" ON "Game"("tenantId","status"); CREATE INDEX "draw_tenant_status_close" ON "Draw"("tenantId","status","closesAt"); CREATE INDEX "draw_game_date" ON "Draw"("gameId","drawDate"); CREATE INDEX "odds_lookup" ON "OddsRule"("tenantId","gameId","betTypeId","active"); CREATE INDEX "limit_lookup" ON "BettingLimit"("tenantId","scope","scopeId","active");
ALTER TABLE "Game" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Market" ENABLE ROW LEVEL SECURITY; ALTER TABLE "BetType" ENABLE ROW LEVEL SECURITY; ALTER TABLE "GameSchedule" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Draw" ENABLE ROW LEVEL SECURITY; ALTER TABLE "OddsRule" ENABLE ROW LEVEL SECURITY; ALTER TABLE "LotteryRule" ENABLE ROW LEVEL SECURITY; ALTER TABLE "BettingLimit" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_game_isolation ON "Game" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_market_isolation ON "Market" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_bet_type_isolation ON "BetType" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_schedule_isolation ON "GameSchedule" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_draw_isolation ON "Draw" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_odds_isolation ON "OddsRule" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_rule_isolation ON "LotteryRule" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_limit_isolation ON "BettingLimit" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
